script.setup:
// fishdraw by Lingdong Huang (MIT, https://github.com/LingDong-/fishdraw): procedurally generated
// fish as plotter polylines, with a made-up Latin name lettered underneath. The source is fetched
// from a pinned commit and run as-is; this scene plays each drawing back like a pen plotter,
// stroke by stroke in fishdraw's own order, then lifts the sheet away and starts the next fish.
const SRC = "https://cdn.jsdelivr.net/gh/LingDong-/fishdraw@a514372de1d05b4aa32a9e35aadec9a5299689a2/fishdraw.js";
const res = await fetch(SRC);
if (!res.ok) throw new Error(`couldn't fetch fishdraw (HTTP ${res.status}) from ${SRC}`);
const lib = new Function(await res.text() +
  "\nreturn { main, binomen, setSeed: function (v) { jsr = v; } };")();

const SW = 520, SH = 320, K = 4; // sheet size (fishdraw's SVG) and canvas pixels per unit
const cv = new OffscreenCanvas(SW * K, SH * K);
const g = cv.getContext("2d");

// A fish as one pen path: [x0, y0, x1, y1, startDistance] per segment, plus pen-up moves.
function makeFish(name) {
  const t0 = performance.now();
  const lines = lib.main(name);
  const ms = performance.now() - t0;
  const segs = [];
  let d = 0, [px, py] = lines[0][0];
  for (const pl of lines) {
    d += Math.hypot(pl[0][0] - px, pl[0][1] - py) * 0.25; // pen-up travel is quicker
    for (let j = 1; j < pl.length; j++) {
      const [ax, ay] = pl[j - 1], [bx, by] = pl[j];
      const l = Math.hypot(bx - ax, by - ay);
      segs.push([ax + 10, ay + 10, bx + 10, by + 10, d, l]);
      d += l;
    }
    [px, py] = pl[pl.length - 1];
  }
  return { name, segs, total: d, ms, drawn: 0, i: 0, pen: [10, 10], down: false };
}

function randomName() {
  lib.setSeed(1 + Math.floor(Math.random() * 1e9));
  return lib.binomen();
}

function clear() {
  g.setTransform(1, 0, 0, 1, 0, 0);
  g.fillStyle = "#000";
  g.fillRect(0, 0, cv.width, cv.height);
}

// Draw the pen path from f.drawn up to distance d.
function drawTo(f, d, weight) {
  g.setTransform(K, 0, 0, K, 0, 0);
  g.strokeStyle = "#fff";
  g.lineWidth = weight;
  g.lineCap = "round";
  g.lineJoin = "round";
  g.beginPath();
  const segs = f.segs;
  while (f.i < segs.length) {
    const [ax, ay, bx, by, s0, l] = segs[f.i];
    if (s0 >= d) { f.down = false; break; }
    const a = Math.max(0, f.drawn - s0) / (l || 1), b = Math.min(1, (d - s0) / (l || 1));
    const x0 = ax + (bx - ax) * a, y0 = ay + (by - ay) * a, x1 = ax + (bx - ax) * b, y1 = ay + (by - ay) * b;
    g.moveTo(x0, y0); g.lineTo(x1, y1);
    f.pen = [x1, y1]; f.down = true;
    if (b < 1) break;
    f.i++;
  }
  g.stroke();
  // between strokes the pen travels in the air towards the next one
  if (!f.down && f.i < segs.length) {
    const [nx, ny] = segs[f.i], prev = f.i > 0 ? segs[f.i - 1] : [10, 10, 10, 10];
    const gap = segs[f.i][4] - (f.i > 0 ? prev[4] + prev[5] : 0);
    const t = gap > 0 ? Math.min(1, Math.max(0, (d - (segs[f.i][4] - gap)) / gap)) : 1;
    f.pen = [prev[2] + (nx - prev[2]) * t, prev[3] + (ny - prev[3]) * t];
  }
  f.drawn = Math.min(d, f.total);
}

const gl = ctx.gl, tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);

const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_inkTex;
uniform vec2 u_resolution, u_penPos;
uniform vec3 u_paper, u_inkColor;
uniform float u_fade, u_penOn, u_penDown, u_slide;
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}
float fbm(vec2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { s += a * vnoise(p); p *= 2.03; a *= 0.5; } return s; }
void main() {
  vec2 px = v_uv * u_resolution;
  float sc = min(u_resolution.x / 480.0, u_resolution.y / 290.0) * 0.98;
  vec2 origin = 0.5 * (u_resolution - vec2(520.0, 320.0) * sc);
  vec2 sp = (vec2(px.x, u_resolution.y - px.y) - origin) / sc; // sheet units, y down
  sp.x += u_slide * 800.0;
  vec2 uv = sp / vec2(520.0, 320.0);
  float inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
  float c = texture(u_inkTex, uv).r * inside;
  // a faint wet halo around the lines
  float halo = textureLod(u_inkTex, uv, 3.0).r * inside;
  c = max(c, halo * 0.18);
  c *= u_fade;
  vec2 q = px / u_resolution.y * 9.0;
  float mott = fbm(q * 0.7) - 0.5, fib = fbm(vec2(q.x * 5.0, q.y * 0.6) + 7.0) - 0.5;
  float grain = hash(floor(px)) - 0.5;
  vec3 paper = u_paper * (1.0 + mott * 0.06 + fib * 0.03 + grain * 0.03);
  // ink pools slightly darker where the paper is rougher
  vec3 ink = u_inkColor * (1.0 - 0.15 * fib);
  vec3 col = mix(paper, ink, clamp(c, 0.0, 1.0) * (0.9 + 0.1 * grain));
  // the pen: a nib that presses down while drawing and hovers (with a soft shadow) in between
  vec2 pp = (u_penPos - vec2(u_slide * 800.0, 0.0)) * sc + origin;
  pp.y = u_resolution.y - pp.y;
  float r = length(px - pp) / sc;
  float shadowOff = mix(4.0, 1.0, u_penDown);
  float sh = length(px - pp - vec2(shadowOff, -shadowOff) * sc) / sc;
  col *= 1.0 - u_penOn * 0.18 * smoothstep(5.0, 0.0, sh);
  col = mix(col, u_inkColor * 0.8, u_penOn * smoothstep(2.4, 1.6, r));
  col = mix(col, vec3(1.0), u_penOn * 0.35 * smoothstep(0.9, 0.3, length(px - pp + vec2(0.6, -0.6) * sc) / sc));
  float vig = 1.0 - 0.25 * pow(length((v_uv - 0.5) * vec2(1.0, 0.8)) * 1.35, 2.6);
  outColor = vec4(col * vig, 1.0);
}`;

clear();
const first = makeFish("Hepateras austti");
Object.assign(ctx.state, {
  makeFish, randomName, clear, drawTo, cv, tex, fish: first, phase: "draw", phaseT: 0, weight: null, dirty: true,
  prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs),
});

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const dt = Math.min(ctx.dt, 0.1);
let f = s.fish;
if (u.u_new && (s.phase === "draw" || s.phase === "hold")) { s.phase = "out"; s.phaseT = 0; }
// line weight changed: redraw what is already on the sheet
if (s.weight !== u.u_weight) {
  s.weight = u.u_weight;
  const d = f.drawn;
  s.clear(); f.drawn = 0; f.i = 0;
  if (d > 0) s.drawTo(f, d, s.weight);
  s.dirty = true;
}
s.phaseT += dt;
let slide = 0;
if (s.phase === "draw") {
  s.drawTo(f, f.drawn + u.u_speed * dt, s.weight);
  s.dirty = true;
  if (f.drawn >= f.total) { s.phase = "hold"; s.phaseT = 0; }
} else if (s.phase === "hold") {
  if (s.phaseT > 4) { s.phase = "out"; s.phaseT = 0; }
} else if (s.phase === "out") {
  const t = Math.min(1, s.phaseT / 1.4);
  slide = t * t * (3 - 2 * t);
  if (t >= 1) {
    f = s.fish = s.makeFish(s.randomName());
    s.clear(); s.dirty = true;
    s.phase = "in"; s.phaseT = 0; slide = -1;
  }
} else if (s.phase === "in") {
  const t = Math.min(1, s.phaseT / 1.0);
  slide = -1 + t * t * (3 - 2 * t);
  if (t >= 1) { s.phase = "draw"; s.phaseT = 0; slide = 0; }
}
if (s.dirty) {
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.cv);
  gl.generateMipmap(gl.TEXTURE_2D);
  s.dirty = false;
}
ctx.publish("fish", f.name);
ctx.publish("drawn %", Math.round((100 * f.drawn) / f.total));

gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, {
  u_resolution: ctx.resolution, u_penPos: f.pen, u_paper: u.u_paper, u_inkColor: u.u_ink,
  u_fade: 1, u_penOn: u.u_pen && s.phase === "draw" ? 1 : 0, u_penDown: f.down ? 1 : 0, u_slide: slide,
});
ctx.utils.bindTexture(s.prog, "u_inkTex", s.tex, 0);
ctx.utils.drawFullscreen(s.prog);
